def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=2 or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    a,b=q.pop();cells.append((a,b))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(a+dy,b+dx)
     if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]]==2 and z not in seen:seen.add(z);q.append(z)
   out.append(cells)
 return out
